# Hashti — Backend-only unified test runner
# Run from repository root:
# powershell -ExecutionPolicy Bypass -File .\test-hashti-backend.ps1
# Safe notes: business workflows use a uniquely named disposable database; API checks use existing
# test accounts and read-only fixtures except a reversible favorite add/remove. No frontend lint/build.
$ErrorActionPreference = 'Continue'
$root = (Get-Location).Path
if (-not (Test-Path '.\docker-compose.yml') -and -not (Test-Path '.\compose.yml')) {
  Write-Host 'خطا: اسکریپت را از ریشه پروژه، کنار docker-compose.yml اجرا کن.' -ForegroundColor Red
  exit 2
}
$script:PhaseFailures = 0
$tempRoot = Join-Path $env:TEMP ('hashti-backend-tests-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
$fullPath = Join-Path $tempRoot 'test-full-workflows.ps1'
$safePath = Join-Path $tempRoot 'test-backend-api.ps1'
$full64 = ''
$safe64 = ''
[IO.File]::WriteAllBytes($fullPath, [Convert]::FromBase64String($full64))
[IO.File]::WriteAllBytes($safePath, [Convert]::FromBase64String($safe64))
$results = @()
function Run-Phase([string]$Name, [string]$Path) {
  Write-Host "`n============================================================" -ForegroundColor Cyan
  Write-Host "مرحله: $Name" -ForegroundColor Cyan
  Write-Host '============================================================' -ForegroundColor Cyan
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $Path
  $code = $LASTEXITCODE
  if ($code -eq 0) { Write-Host "نتیجه مرحله: PASS" -ForegroundColor Green }
  else { Write-Host "نتیجه مرحله: FAIL (exit=$code)" -ForegroundColor Red; $script:PhaseFailures++ }
  $script:results += [pscustomobject]@{ Stage=$Name; ExitCode=$code }
}
try {
  Run-Phase 'گردش‌کارهای کسب‌وکار روی دیتابیس موقت' $fullPath
  Run-Phase 'API، نشست‌ها، نقش‌ها، دسترسی‌ها و تست‌های امن بک‌اند' $safePath
  Write-Host "`n============================================================" -ForegroundColor Cyan
  Write-Host 'مرحله: کنترل‌های ایستای بک‌اند' -ForegroundColor Cyan
  Write-Host '============================================================' -ForegroundColor Cyan
  & docker compose exec -T db pg_isready -U postgres -d amlak *> $null
  if ($LASTEXITCODE -eq 0) { Write-Host '[PASS] PostgreSQL readiness' -ForegroundColor Green } else { Write-Host '[FAIL] PostgreSQL readiness' -ForegroundColor Red; $script:PhaseFailures++ }
  & docker compose exec -T backend npx prisma validate
  if ($LASTEXITCODE -eq 0) { Write-Host '[PASS] Prisma schema validation' -ForegroundColor Green } else { Write-Host '[FAIL] Prisma schema validation' -ForegroundColor Red; $script:PhaseFailures++ }
  & docker compose exec -T backend npx tsc --noEmit
  if ($LASTEXITCODE -eq 0) { Write-Host '[PASS] Backend TypeScript check' -ForegroundColor Green } else { Write-Host '[FAIL] Backend TypeScript check' -ForegroundColor Red; $script:PhaseFailures++ }
  Write-Host "`n================ خلاصه تست بک‌اند ================" -ForegroundColor Cyan
  $results | ForEach-Object { $status = if ($_.ExitCode -eq 0) {'PASS'} else {'FAIL'}; Write-Host "[$status] $($_.Stage) (exit=$($_.ExitCode))" }
  if ($script:PhaseFailures -eq 0) { Write-Host 'تمام مراحل بک‌اند موفق شدند.' -ForegroundColor Green; exit 0 }
  else { Write-Host "$script:PhaseFailures مرحله بک‌اند ناموفق بود؛ جزئیات بالا را بررسی کن." -ForegroundColor Red; exit 1 }
}
finally {
  Remove-Item $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
}
